/**
 * Auto-title generator providers: one-shot, non-streaming chat completion over HTTP.
 *
 * Offered: OpenRouter with an API key (OpenAI-compatible repo harness plugins register theirs at boot); Codex and Claude with an API key, or on a
 * ChatGPT / Claude subscription via a one-shot local CLI/SDK call (chat-title-plan-runners.js).
 * Other CLI/PTY/SDK-only harnesses are listed as unavailable with a reason — a title is never generated by running a chat or a delegation.
 *
 * Every adapter shares one interface: generate({ prompt, model, signal, maxOutputTokens? }) => string. Keys are
 * read per call and never returned, logged or put into error messages.
 */

import {
  DEFAULT_AUTO_TITLE_MODEL,
  getAutoTitleSettings,
  loadSettings,
} from './persist/settings.js';
import { isHarnessEnabled } from './harness-enabled.js';
import {
  getOpenRouterRequestHeaders,
  getRawOpenRouterApiKeyCandidate,
  isValidOpenRouterApiKeyFormat,
} from './providers/openrouter/openrouter-api-key.ts';
import { generateTitleViaClaudePlan, generateTitleViaCodexPlan } from './chat-title-plan-runners.js';
import { hasCodexChatGptAuth } from './codex/codex-chatgpt-auth.ts';
import { listFallbackCodexModels, resolveDefaultCodexModel } from './codex/codex-models.ts';
import { hasClaudeSubscriptionAuth } from './claude/claude-subscription.ts';
import { getEffectiveCodexApiKey } from './codex/codex-api-key.ts';
import { getCodexAuthMode } from './codex/codex-auth-mode.ts';
import {
  getEffectiveClaudeApiKey,
  isClaudeThirdPartyProviderConfigured,
} from './claude/claude-api-key.ts';
import { getClaudeAuthMode } from './claude/claude-auth-mode.ts';
import { resolveClaudeApiBaseUrl } from './claude/claude-models.ts';

export const OPENROUTER_CHAT_URL = 'https://openrouter.ai/api/v1/chat/completions';
const OPENAI_CHAT_URL = 'https://api.openai.com/v1/chat/completions';
const ANTHROPIC_VERSION = '2023-06-01';
const MAX_OUTPUT_TOKENS = 60;

/** Reason codes returned for unavailable providers (the UI maps them to localized text). */
export const TITLE_PROVIDER_REASONS = Object.freeze({
  harnessDisabled: 'harness_disabled',
  noKey: 'no_key',
  invalidKeyFormat: 'invalid_key_format',
  authMode: 'auth_mode',
  unsupported: 'unsupported',
});

const REASON_TEXT = Object.freeze({
  harness_disabled: 'harness disabled in Settings',
  no_key: 'no API key',
  invalid_key_format: 'API key has a wrong format (OpenRouter keys start with sk-or-v1-)',
  auth_mode: 'harness does not use an API key in its current auth mode (third-party cloud provider)',
  unsupported: 'no one-shot HTTP API (CLI/SDK harness)',
});

/** Harnesses that are never title generators, shown as unavailable. */
const UNSUPPORTED_HARNESSES = Object.freeze([
  { id: 'sdk', label: 'Cursor SDK' },
  { id: 'opencode', label: 'OpenCode' },
  { id: 'codebuddy', label: 'CodeBuddy' },
]);

function model(id, label = id) {
  return { id, label };
}

/**
 * @param {string} baseUrl
 * @param {string} path
 */
function joinUrl(baseUrl, path) {
  return `${String(baseUrl).replace(/\/+$/, '')}${path}`;
}

/**
 * @param {string} url
 * @param {Record<string, string>} headers
 * @param {Record<string, unknown>} body
 * @param {AbortSignal | undefined} signal
 * @returns {Promise<Record<string, any>>}
 */
async function postJson(url, headers, body, signal) {
  const response = await fetch(url, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...headers },
    body: JSON.stringify(body),
    signal,
  });
  if (!response.ok) {
    const err = new Error(`title generator HTTP ${response.status}`);
    /** @type {any} */ (err).status = response.status;
    throw err;
  }
  return response.json();
}

/**
 * Completion budget for one call. Title generation stays at the shipped 60
 * tokens; a caller that reuses this one-shot seam for a longer answer (the
 * history summary) can pass a larger `maxOutputTokens`.
 *
 * @param {unknown} value
 * @returns {number}
 */
function resolveMaxOutputTokens(value) {
  const parsed = Number(value);
  return Number.isFinite(parsed) && parsed > 0 ? Math.floor(parsed) : MAX_OUTPUT_TOKENS;
}

/**
 * OpenAI-compatible chat/completions body + response parsing.
 *
 * @param {string} url
 * @param {Record<string, string>} headers
 * @param {TitleGenerateInput} input
 */
async function openAiCompatible(url, headers, { prompt, model: modelId, signal, maxOutputTokens }) {
  const json = await postJson(url, headers, {
    model: modelId,
    max_tokens: resolveMaxOutputTokens(maxOutputTokens),
    temperature: 0.2,
    messages: [{ role: 'user', content: prompt }],
  }, signal);
  const content = json?.choices?.[0]?.message?.content;
  return typeof content === 'string' ? content : '';
}

/** ChatGPT-plan Codex / Claude subscription: one-shot via the local CLI/SDK login, no API key. */
function usesCodexPlan() {
  return getCodexAuthMode() === 'chatgpt';
}
function usesClaudePlan() {
  return getClaudeAuthMode() === 'subscription';
}

/**
 * @typedef {{ prompt: string, model: string, signal?: AbortSignal, maxOutputTokens?: number }} TitleGenerateInput
 */

/**
 * @typedef {{
 *   id: string,
 *   label: string,
 *   defaultModel: () => string,
 *   models: () => Array<{ id: string, label: string }>,
 *   check: () => string,
 *   generate: (input: TitleGenerateInput) => Promise<string>,
 * }} TitleProviderAdapter
 */

/** @type {TitleProviderAdapter[]} — order is the 'auto' priority. */
export const TITLE_PROVIDER_ADAPTERS = [
  {
    id: 'openrouter',
    label: 'OpenRouter',
    defaultModel: () => DEFAULT_AUTO_TITLE_MODEL,
    models: () => [
      model(DEFAULT_AUTO_TITLE_MODEL),
      model('google/gemini-2.0-flash-001'),
      model('anthropic/claude-3.5-haiku'),
    ],
    check() {
      const raw = getRawOpenRouterApiKeyCandidate();
      if (!raw) return TITLE_PROVIDER_REASONS.noKey;
      return isValidOpenRouterApiKeyFormat(raw) ? '' : TITLE_PROVIDER_REASONS.invalidKeyFormat;
    },
    generate: (input) => openAiCompatible(OPENROUTER_CHAT_URL, getOpenRouterRequestHeaders(), input),
  },
  {
    id: 'codex',
    get label() { return usesCodexPlan() ? 'Codex (ChatGPT plan)' : 'Codex (OpenAI)'; },
    defaultModel: () => (usesCodexPlan() ? resolveDefaultCodexModel() : 'gpt-4o-mini'),
    models() {
      if (!usesCodexPlan()) return [model('gpt-4o-mini'), model('gpt-4.1-mini')];
      const ids = [...new Set(listFallbackCodexModels().map((m) => String(m.value).split('::')[0]))];
      return ids.map((id) => model(id));
    },
    check() {
      if (usesCodexPlan()) return hasCodexChatGptAuth() ? '' : TITLE_PROVIDER_REASONS.noKey;
      return getEffectiveCodexApiKey() ? '' : TITLE_PROVIDER_REASONS.noKey;
    },
    generate: (input) => (usesCodexPlan()
      ? generateTitleViaCodexPlan(input)
      : openAiCompatible(OPENAI_CHAT_URL, { Authorization: `Bearer ${getEffectiveCodexApiKey()}` }, input)),
  },
  {
    id: 'claude',
    get label() { return usesClaudePlan() ? 'Claude (subscription)' : 'Claude (Anthropic)'; },
    defaultModel: () => (usesClaudePlan() ? 'haiku' : 'claude-haiku-4-5-20251001'),
    models: () => (usesClaudePlan()
      ? [model('haiku', 'Haiku'), model('sonnet', 'Sonnet')]
      : [model('claude-haiku-4-5-20251001', 'Claude Haiku 4.5')]),
    check() {
      if (usesClaudePlan()) return hasClaudeSubscriptionAuth() ? '' : TITLE_PROVIDER_REASONS.noKey;
      if (isClaudeThirdPartyProviderConfigured()) return TITLE_PROVIDER_REASONS.authMode;
      return getEffectiveClaudeApiKey() ? '' : TITLE_PROVIDER_REASONS.noKey;
    },
    async generate({ prompt, model: modelId, signal, maxOutputTokens }) {
      if (usesClaudePlan()) return generateTitleViaClaudePlan({ prompt, model: modelId, signal });
      const json = await postJson(
        joinUrl(resolveClaudeApiBaseUrl(), '/v1/messages'),
        { 'x-api-key': getEffectiveClaudeApiKey(), 'anthropic-version': ANTHROPIC_VERSION },
        {
          model: modelId,
          max_tokens: resolveMaxOutputTokens(maxOutputTokens),
          temperature: 0.2,
          messages: [{ role: 'user', content: prompt }],
        },
        signal,
      );
      const block = Array.isArray(json?.content) ? json.content.find((b) => b?.type === 'text') : null;
      return typeof block?.text === 'string' ? block.text : '';
    },
  },
];

/**
 * @typedef {Object} OptionalTitleProviderSpec
 * @property {string} id Harness id (equals the plugin id).
 * @property {string} label
 * @property {string} [insertBefore] Id of the adapter this one precedes in the 'auto' priority (default: appended).
 * @property {() => string} defaultModel
 * @property {() => Array<{ value: string, label?: string }>} fallbackModels
 * @property {() => boolean} hasCredentials
 * @property {() => string} baseUrl OpenAI-compatible base URL ('/chat/completions' is appended).
 * @property {() => string} apiKey
 * @property {(modelId: string) => string} [remapModel]
 */

/**
 * Side-effect-free collision check used before a multi-registry plugin load.
 *
 * @param {string} id
 * @returns {boolean}
 */
export function hasTitleProviderAdapter(id) {
  return TITLE_PROVIDER_ADAPTERS.some((adapter) => adapter.id === id);
}

/**
 * Register the one-shot title generator of a repo harness plugin (an
 * OpenAI-compatible endpoint keyed by an API key). An id that is already
 * listed is refused so a plugin can never shadow a built-in adapter.
 *
 * @param {OptionalTitleProviderSpec} spec
 * @returns {{ ok: true } | { ok: false, code: 'id_collision', error: string }}
 */
export function registerOptionalTitleProvider(spec) {
  if (hasTitleProviderAdapter(spec.id)) {
    return { ok: false, code: 'id_collision', error: `Title provider "${spec.id}" is already registered` };
  }
  const remap = spec.remapModel || ((/** @type {string} */ id) => id);
  /** @type {TitleProviderAdapter} */
  const adapter = {
    id: spec.id,
    label: spec.label,
    defaultModel: spec.defaultModel,
    models: () => spec.fallbackModels().map((m) => model(m.value, m.label || m.value)),
    check: () => (spec.hasCredentials() ? '' : TITLE_PROVIDER_REASONS.noKey),
    generate: (input) => openAiCompatible(
      joinUrl(spec.baseUrl(), '/chat/completions'),
      { Authorization: `Bearer ${spec.apiKey()}` },
      { ...input, model: remap(input.model) },
    ),
  };
  const index = spec.insertBefore ? TITLE_PROVIDER_ADAPTERS.findIndex((row) => row.id === spec.insertBefore) : -1;
  if (index === -1) TITLE_PROVIDER_ADAPTERS.push(adapter);
  else TITLE_PROVIDER_ADAPTERS.splice(index, 0, adapter);
  return { ok: true };
}

/**
 * @param {string} id
 * @returns {TitleProviderAdapter | undefined}
 */
export function getTitleProviderAdapter(id) {
  return TITLE_PROVIDER_ADAPTERS.find((a) => a.id === id);
}

/**
 * @param {string} reason
 * @returns {string}
 */
export function describeTitleProviderReason(reason) {
  return REASON_TEXT[reason] || reason || 'unavailable';
}

/**
 * @param {TitleProviderAdapter} adapter
 * @param {Record<string, any> | null} [settings]
 * @returns {string} reason code or '' when usable
 */
function unavailableReason(adapter, settings) {
  if (!isHarnessEnabled(adapter.id, settings?.enabledHarnesses)) return TITLE_PROVIDER_REASONS.harnessDisabled;
  return adapter.check();
}

/**
 * Provider list for Settings: { id, label, available, reason, reasonText, models[], defaultModel }.
 * Never includes key material.
 *
 * @param {Record<string, any> | null} [settings] - loadSettings() result
 */
export function listTitleProviders(settings = null) {
  const cfg = settings || loadSettings();
  /** @type {Array<{ id: string, label: string, viaPlan?: boolean, available: boolean, reason: string, reasonText: string, defaultModel: string, models: Array<{ id: string, label: string }> }>} */
  const rows = TITLE_PROVIDER_ADAPTERS.map((adapter) => {
    const reason = unavailableReason(adapter, cfg);
    return {
      id: adapter.id,
      label: adapter.label,
      viaPlan: (adapter.id === 'codex' && usesCodexPlan()) || (adapter.id === 'claude' && usesClaudePlan()),
      available: !reason,
      reason,
      reasonText: reason ? describeTitleProviderReason(reason) : '',
      defaultModel: adapter.defaultModel(),
      models: adapter.models(),
    };
  });
  for (const row of UNSUPPORTED_HARNESSES) {
    rows.push({
      id: row.id,
      label: row.label,
      available: false,
      reason: TITLE_PROVIDER_REASONS.unsupported,
      reasonText: describeTitleProviderReason(TITLE_PROVIDER_REASONS.unsupported),
      defaultModel: '',
      models: [],
    });
  }
  return rows;
}

/**
 * Model actually sent to a provider: the stored one when valid for it, else the provider default.
 * OpenRouter accepts any id (backward compatible with the free-form setting).
 *
 * @param {TitleProviderAdapter} adapter
 * @param {string} requested
 */
export function pickProviderModel(adapter, requested) {
  const wanted = String(requested || '').trim();
  if (wanted && (adapter.id === 'openrouter' || adapter.models().some((m) => m.id === wanted))) return wanted;
  return adapter.defaultModel();
}

/**
 * Resolves the provider/model for the current settings.
 *
 * @param {{ provider?: string, model?: string }} [autoTitle] - defaults to the stored autoTitle
 * @param {Record<string, any> | null} [settings]
 * @returns {{ ok: true, provider: string, model: string, adapter: TitleProviderAdapter }
 *   | { ok: false, provider: string, reason: string, message: string }}
 */
export function resolveTitleProvider(autoTitle = null, settings = null) {
  const cfg = settings || loadSettings();
  const selected = autoTitle || getAutoTitleSettings(cfg);
  const requested = selected.provider || 'auto';
  if (requested === 'auto') {
    const reasons = [];
    for (const adapter of TITLE_PROVIDER_ADAPTERS) {
      const reason = unavailableReason(adapter, cfg);
      if (!reason) {
        return { ok: true, provider: adapter.id, model: pickProviderModel(adapter, selected.model), adapter };
      }
      reasons.push(`${adapter.id}: ${describeTitleProviderReason(reason)}`);
    }
    return {
      ok: false,
      provider: 'auto',
      reason: 'none_available',
      message: `no provider available (${reasons.join('; ')})`,
    };
  }
  const adapter = getTitleProviderAdapter(requested);
  if (!adapter) {
    return { ok: false, provider: requested, reason: 'unknown_provider', message: `unknown provider "${requested}"` };
  }
  const reason = unavailableReason(adapter, cfg);
  if (reason) {
    return {
      ok: false,
      provider: requested,
      reason,
      message: `provider ${requested} unavailable: ${describeTitleProviderReason(reason)}`,
    };
  }
  return { ok: true, provider: requested, model: pickProviderModel(adapter, selected.model), adapter };
}

/**
 * Default generator used by the title service: resolves the configured provider on every call.
 * Returns null when no provider is usable (the service logs the reason via explainTitleGeneratorGap).
 *
 * @param {{ prompt: string, model?: string, signal?: AbortSignal, maxOutputTokens?: number }} input
 * @returns {Promise<string | null>}
 */
export async function generateTitleViaProvider({ prompt, model: requestedModel, signal, maxOutputTokens }) {
  const resolved = resolveTitleProvider();
  if (!resolved.ok) return null;
  const run = (/** @type {TitleProviderAdapter} */ adapter, /** @type {string} */ fallbackModel) => adapter.generate({
    prompt,
    model: requestedModel ? pickProviderModel(adapter, requestedModel) : fallbackModel,
    signal,
    maxOutputTokens,
  });
  const cfg = loadSettings();
  const selected = getAutoTitleSettings(cfg);
  if ((selected.provider || 'auto') !== 'auto') return run(resolved.adapter, resolved.model);
  // 'auto' picks by key presence only. A key that is present but rejected (or a
  // provider that is unreachable) must not block titles while another
  // configured provider works, so try the next one and rest the failed one.
  const now = Date.now();
  let lastError = null;
  for (const adapter of TITLE_PROVIDER_ADAPTERS) {
    if (unavailableReason(adapter, cfg)) continue;
    if ((autoTitleProviderCooldown.get(adapter.id) || 0) > now) continue;
    try {
      return await run(adapter, pickProviderModel(adapter, selected.model));
    } catch (err) {
      if (signal?.aborted || !isTitleProviderFailover(err)) throw err;
      autoTitleProviderCooldown.set(adapter.id, now + AUTO_TITLE_PROVIDER_COOLDOWN_MS);
      lastError = err;
    }
  }
  if (lastError) throw lastError;
  // Every usable provider is resting: retry the preferred one.
  return run(resolved.adapter, resolved.model);
}

/** How long 'auto' skips a provider after an auth or network failure. */
const AUTO_TITLE_PROVIDER_COOLDOWN_MS = 10 * 60 * 1000;
/** @type {Map<string, number>} provider id -> epoch ms until which it is skipped */
const autoTitleProviderCooldown = new Map();

/**
 * Errors worth trying another provider for: rejected credentials, missing
 * access, rate limits, server errors and network failures. Bad requests and
 * aborts are not.
 *
 * @param {unknown} err
 * @returns {boolean}
 */
function isTitleProviderFailover(err) {
  const status = Number(/** @type {any} */ (err)?.status) || 0;
  if (status) return status === 401 || status === 403 || status === 429 || status >= 500;
  return /fetch failed|ECONN|ENOTFOUND|ETIMEDOUT|EAI_AGAIN/i.test(String(/** @type {any} */ (err)?.message || ''));
}

/** Test seam: forget provider cooldowns. */
export function resetTitleProviderCooldowns() {
  autoTitleProviderCooldown.clear();
}

/**
 * Human-readable reason why no generator can run now ('' when one can).
 * @returns {string}
 */
export function explainTitleGeneratorGap() {
  const resolved = resolveTitleProvider();
  return resolved.ok ? '' : /** @type {{ message: string }} */ (resolved).message;
}
